add_action( 'restrict_manage_posts', 'perfectpixel_admin_sale_filter_select', 20 );
add_filter( 'request', 'perfectpixel_admin_sale_filter_query' );

function perfectpixel_admin_sale_filter_select( $post_type ) {
	if ( 'product' !== $post_type ) {
		return;
	}
	$current = isset( $_GET['perfectpixel_sale'] ) ? sanitize_key( $_GET['perfectpixel_sale'] ) : '';
	echo '<select name="perfectpixel_sale">';
	foreach ( array( '' => 'Όλες οι τιμές', 'yes' => 'Σε προσφορά', 'no' => 'Χωρίς προσφορά' ) as $value => $label ) {
		printf( '<option value="%s"%s>%s</option>', esc_attr( $value ), selected( $current, $value, false ), esc_html( $label ) );
	}
	echo '</select>';
}

function perfectpixel_admin_sale_filter_query( $vars ) {
	global $typenow;
	if ( ! is_admin() || 'product' !== $typenow || empty( $_GET['perfectpixel_sale'] ) ) {
		return $vars;
	}
	$ids = array_map( 'intval', wc_get_product_ids_on_sale() );
	if ( 'yes' === $_GET['perfectpixel_sale'] ) {
		$vars['post__in'] = $ids ? $ids : array( 0 );
	} elseif ( 'no' === $_GET['perfectpixel_sale'] && $ids ) {
		$vars['post__not_in'] = $ids;
	}
	return $vars;
}
